#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Import telegram tools
const { sendMessage, escapeHtml } = require('../event_handler/tools/telegram');

async function main() {
  // Get credentials from environment
  const botToken = process.env.TELEGRAM_BOT_TOKEN;
  const chatId = process.env.TELEGRAM_CHAT_ID;

  if (!botToken || !chatId) {
    console.error('❌ Missing Telegram credentials');
    console.error('Required environment variables:');
    console.error('  - TELEGRAM_BOT_TOKEN');
    console.error('  - TELEGRAM_CHAT_ID');
    process.exit(1);
  }

  // Read the briefing
  const briefingPath = path.join(__dirname, 'sterling_briefing.md');
  let briefing = fs.readFileSync(briefingPath, 'utf8');

  // Convert markdown to HTML for Telegram
  briefing = briefing
    // Headers
    .replace(/^### (.*?)$/gm, '<b>$1</b>')
    .replace(/^## (.*?)$/gm, '<b><u>$1</u></b>')
    .replace(/^# (.*?)$/gm, '<b><u>$1</u></b>')
    // Bold
    .replace(/\*\*(.*?)\*\*/g, '<b>$1</b>')
    // Italic
    .replace(/\*(.*?)\*/g, '<i>$1</i>')
    // Code
    .replace(/`(.*?)`/g, '<code>$1</code>')
    // Horizontal rules
    .replace(/^---$/gm, '━━━━━━━━━━━━━━━━')
    // Remove extra newlines but keep paragraph spacing
    .replace(/\n{3,}/g, '\n\n');

  // Send to Telegram
  console.log('📤 Sending Sterling Intelligence Briefing to Telegram...');

  try {
    await sendMessage(botToken, chatId, briefing, { disablePreview: true });
    console.log('✅ Briefing sent successfully!');
  } catch (error) {
    console.error('❌ Failed to send briefing:', error.message);
    process.exit(1);
  }
}

main().catch(console.error);

